import json, socket, concurrent.futures, subprocess, datetime, urllib.request, ctypes
def tcp(p):
 try:
  with socket.create_connection(('127.0.0.1',p),1.4):return 'CONNECTED'
 except Exception as e:return type(e).__name__
def get(arg):
 name,url=arg
 try:
  with urllib.request.urlopen(url,timeout=2) as r:return {'name':name,'status':r.status,'bytes':len(r.read(32768))}
 except Exception as e:return {'name':name,'error':type(e).__name__}
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
 futs={p:pool.submit(tcp,p) for p in [17448,17410,17447]}
 checks={name:pool.submit(get,(name,url)) for name,url in [
  ('bridge_health','http://127.0.0.1:17448/api/health'),
  ('bridge_operator','http://127.0.0.1:17448/api/operator-lifecycle'),
  ('chrome_version','http://127.0.0.1:17410/json/version'),
  ('chrome_targets','http://127.0.0.1:17410/json/list')]}
 port={str(k):v.result() for k,v in futs.items()}
 http=[f.result() for f in checks.values()]
try:
 handle=ctypes.windll.kernel32.OpenProcess(0x1000,False,13436)
 alive=bool(handle)
 if handle:ctypes.windll.kernel32.CloseHandle(handle)
except Exception as e:alive=None
try:
 git=subprocess.run(['git.exe','-C',r'E:\WebAIBridge','rev-parse','HEAD'],capture_output=True,text=True,timeout=4).stdout.strip()
except Exception as e:git='UNAVAILABLE'
print(json.dumps({'at':datetime.datetime.now().isoformat(timespec='seconds'),'tcp':port,'http':http,'originalChromePid13436Alive':alive,'liveGitSHA':git,'noMutations':True},ensure_ascii=True)[:3800])
